S['NONG2111A'] = [{'k': 'noti', 'ch': 'Mở đầu', 'cap': ('KHỐI NGOẠI BÁN NGHÌN TỶ', 'AI ĐANG ÔM HÀNG?'), 'cols': ((255, 255, 255), (239, 68, 68)), 'noti': {'gio': '15:05', 'ngay': 'Thứ Năm', 'items': [('Tin tức', 'Chứng khoán', 'VN-Index thủng mốc 1.700 điểm, khối ngoại bán ròng gần 1.000 tỷ đồng', (56, 189, 248)), ('Zalo', 'Chứng khoán chợ vải', 'Tây tháo chạy rồi, ai còn cầm hàng là cầm túi cho Tây', (239, 68, 68)), ('Zalo', 'Chứng khoán chợ vải', 'Thôi tắt máy đi chị em, hoảng quá', (255, 196, 0))]}, 'say': 'Ba giờ chiều thứ Năm, mười chín tháng mười một, chị Hạnh đang gấp vải ở sạp chợ Tân Bình thì điện thoại rung liên tục. Tin đầu tiên: VN Index vừa thủng mốc một nghìn bảy trăm điểm, phiên giảm thứ ba liên tiếp, khối ngoại bán ròng gần một nghìn tỷ đồng. Ngay bên dưới, nhóm Zalo chứng khoán của mấy chị em trong chợ nhảy liên tục: Tây tháo chạy rồi, ai còn cầm hàng là đang cầm túi cho Tây.'}, {'k': 'bignum', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('CẢ NĂM 2025 LÀ KỶ LỤC', '10 THÁNG 2026 ĐÃ GẦN BẰNG'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': 122000, 'fmt': '{:,.0f}', 'unit': ' tỷ đồng', 'top': 'KHỐI NGOẠI BÁN RÒNG TRÊN HOSE', 'sub': '10 tháng 2026, chưa tháng nào mua ròng', 'col': (239, 68, 68), 'say': 'Chị Hạnh có sáu trăm triệu đồng trong tài khoản chứng khoán, là tiền lời bán vải dành dụm mấy năm, không vay đồng nào. Chị đang lỗ, bán bây giờ là chốt lỗ, mà giữ thì sợ cầm túi cho Tây. Từ đầu năm, khối ngoại đã bán ròng gần một trăm hai mươi hai nghìn tỷ đồng trên sàn HOSE. Con số này đã gần bằng cả năm hai nghìn không trăm hai mươi lăm, năm bán ròng kỷ lục. Người nước ngoài bán, vậy ai đang mua? Câu trả lời nằm ở một con số rất ít người đọc tới.'}, {'k': 'noti', 'ch': 'Chương 1 – Hai phiên mất 37 điểm', 'cap': ('2 PHIÊN MẤT 37 ĐIỂM', 'KHỐI NGOẠI XẢ KHOẢNG 2.100 TỶ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'noti': {'gio': '20:45', 'ngay': 'Thứ Năm', 'items': [('Bảng giá', 'VN-Index 18/11', '1.703,01 điểm, giảm 23,71 điểm, 539 mã giảm', (239, 68, 68)), ('Tin tức', 'Khối ngoại 18/11', 'Bán ròng 1.114 tỷ đồng trên HOSE', (239, 68, 68)), ('Bảng giá', 'VN-Index 19/11', '1.689,62 điểm, giảm 13,39 điểm, thấp nhất một tháng', (239, 68, 68))]}, 'say': 'Tối thứ Năm, chị Hạnh kéo lại thông báo của hai phiên gần nhất. Thứ Tư mười tám, VN Index mất hơn hai mươi ba điểm, khối ngoại bán ròng hơn một nghìn một trăm tỷ trên HOSE. Thứ Năm mười chín, chỉ số mất thêm hơn mười ba điểm, về mức thấp nhất một tháng. Hai phiên mất ba mươi bảy điểm, khối ngoại xả khoảng hai nghìn một trăm tỷ nếu gộp hai phiên. Riêng tháng mười họ bán hơn hai mươi ba nghìn bảy trăm tỷ, gần như phiên nào cũng bán.'}, {'k': 'bignum', 'ch': 'Chương 2 – Ai đang mua đối ứng?', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('NGƯỜI VIỆT ĐANG MUA LẠI', 'TỪ ĐẦU NĂM ĐẾN 4/11'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 123000, 'fmt': '{:,.0f}', 'unit': ' tỷ đồng', 'top': 'NHÀ ĐẦU TƯ TRONG NƯỚC MUA RÒNG', 'sub': 'Trên HOSE, từ đầu năm đến 4/11/2026', 'col': (255, 196, 0), 'say': 'Và đúng là có người mua. Từ đầu năm đến hết ngày bốn tháng mười một, nhà đầu tư trong nước đã mua ròng hơn một trăm hai mươi ba nghìn tỷ đồng cổ phiếu trên HOSE. Trong đó có cá nhân như chị Hạnh, có quỹ nội, có tự doanh của các công ty chứng khoán. Nghe tới đây, nhóm Zalo càng tin mình đúng: Tây bán, người Việt ôm hết hàng.'}, {'k': 'call', 'anh': 'Tan Dinh Market||Ben Thanh Market', 'cap': ('"BÁN RÒNG KHÔNG CÓ NGHĨA', 'LÀ BÁN CHO CHỊ"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'call': {'ten': 'Anh Phong', 'phu': 'Làm phân tích ở một quỹ đầu tư', 'mau': (56, 189, 248), 'loi': ['Bán ròng không có nghĩa là bán cho chị', 'Chị mở lại tuần đầu tháng 10 mà xem']}, 'say': 'Chị Hạnh gọi cho anh Phong, khách quen làm phân tích ở một quỹ đầu tư, hỏi thẳng: em có đang cầm túi cho Tây không? Anh Phong cười: bán ròng không có nghĩa là bán cho chị. Chị mở lại tuần đầu tháng mười, tuần khối ngoại bán ròng gần mười bốn nghìn tỷ, xem họ bán cho ai và bán bằng cách nào.'}, {'k': 'giay', 'ch': 'Chương 3 – Tuần bán mạnh nhất: phần lớn là thỏa thuận', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('13.921 TỶ BÁN RÒNG', 'CHỈ 1.269 TỶ KHỚP LỆNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'TUẦN 5–9/10/2026 TRÊN HOSE', 'so': 'Theo VnEconomy, 11/10/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Khối ngoại bán ròng tổng cộng 13.921 tỷ đồng.', '13.921 TỶ'), ('Riêng khớp lệnh: 1.269 tỷ.', 'KHỚP LỆNH'), ('Một lô thỏa thuận khoảng 9.600 tỷ, bán cho nhà đầu tư trong nước.', 'MỘT LÔ'), ('Hơn 90% số bán ròng là thỏa thuận.', 'THỎA THUẬN')]}, 'say': 'Đây là cú lật đầu tiên. Tuần đó khối ngoại bán ròng mười ba nghìn chín trăm hai mươi mốt tỷ đồng. Nhưng phần khớp lệnh, nơi chị Hạnh và hàng triệu nhà đầu tư cá nhân đặt lệnh, chỉ khoảng một nghìn hai trăm sáu mươi chín tỷ. Riêng một cổ phiếu hàng tiêu dùng có một lô thỏa thuận khoảng chín nghìn sáu trăm tỷ, bán thẳng cho nhà đầu tư trong nước. Tức là hơn chín mươi phần trăm số bán ròng tuần đó là thỏa thuận giữa các bên lớn, không phải lệnh bán tháo đổ lên đầu nhà đầu tư nhỏ lẻ.'}, {'k': 'chat', 'cap': ('"VẬY PHIÊN THỨ TƯ 1.100 TỶ', 'THÌ SAO EM?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'chat': {'ten': 'Anh Sơn', 'tv': 'Đang hoạt động', 'gio': '21:10', 'mau': (34, 197, 94), 'msgs': [('me', 'Tuần bán gần 14.000 tỷ thì khoảng 12.600 tỷ là thỏa thuận'), ('Anh Sơn', 'Vậy phiên thứ Tư hơn 1.100 tỷ thì sao?'), ('me', 'Hai phiên này bán thật, chỉ số giảm thật anh ạ')]}, 'say': 'Chị Hạnh nhắn cho chồng, anh Sơn: tuần đó khoảng mười hai nghìn sáu trăm tỷ là thỏa thuận. Anh Sơn hỏi lại rất đúng: vậy phiên thứ Tư hơn một nghìn một trăm tỷ thì sao? Chị Hạnh nhắn tiếp: hai phiên này bán thật, chỉ số giảm thật anh ạ. Ở đây em xin nói rõ với anh chị: khối ngoại bán không vô hại. Nhưng con số tổng không cho anh chị biết ai đang ôm hàng.'}, {'k': 'cards', 'ch': 'Chương 4 – Tiền ngoại rút đi đâu?', 'anh': 'Taipei skyline||Seoul skyline', 'cap': ('KHÔNG CHỈ VIỆT NAM', '7 THỊ TRƯỜNG CHÂU Á BỊ RÚT'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('49,77 tỷ USD', '7 thị trường châu Á, tháng 10', 'Theo LSEG'), ('30,68 tỷ USD', 'Riêng Đài Loan', 'Cao nhất từ 2008'), ('14,59 tỷ USD', 'Hàn Quốc', 'Tháng 11 vẫn bị bán')], 'say': 'Cú lật thứ hai nằm ngoài biên giới. Theo dữ liệu của LSEG, chỉ riêng tháng mười, khối ngoại bán ròng gần năm mươi tỷ đô la cổ phiếu ở bảy thị trường châu Á mới nổi, trong đó có Việt Nam. Đài Loan bị rút hơn ba mươi tỷ đô la, mức cao nhất ít nhất từ năm hai nghìn không trăm lẻ tám. Hàn Quốc gần mười lăm tỷ đô la, và sang tháng mười một hai nơi này vẫn bị bán tiếp. Việt Nam chỉ là một góc nhỏ của làn sóng đó.'}, {'k': 'bignum', 'anh': 'Wall Street||New York Stock Exchange', 'cap': ('CÙNG LÚC ĐÓ', 'TIỀN ĐỔ MẠNH VÀO MỸ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 55.44, 'fmt': '{:,.2f}', 'unit': ' tỷ USD', 'top': 'ETF CỔ PHIẾU MỸ HÚT RÒNG', 'sub': 'Chỉ trong tuần 9–13/11/2026', 'col': (255, 196, 0), 'say': 'Cùng lúc đó, tiền lại đổ mạnh vào Mỹ. Chỉ trong tuần chín đến mười ba tháng mười một, các quỹ ETF cổ phiếu tại Mỹ hút ròng hơn năm mươi lăm tỷ đô la. Chị Hạnh đọc tới đây thì dừng lại. Hóa ra nhóm Zalo nhìn sai chỗ: người nước ngoài không chỉ bỏ Việt Nam, họ đang rút khỏi cả một vùng. Chị gọi lại cho anh Phong để hỏi vì sao.'}, {'k': 'call', 'anh': 'Wall Street||New York Stock Exchange', 'cap': ('"TRÁI PHIẾU MỸ TỪNG TRẢ 5,3%', 'QUỸ NÀO CŨNG PHẢI SO"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'call': {'ten': 'Anh Phong', 'phu': 'Làm phân tích ở một quỹ đầu tư', 'mau': (56, 189, 248), 'loi': ['Trái phiếu Mỹ 10 năm từng trả 5,3%', 'Quỹ nào cũng phải so Việt Nam với con số đó']}, 'say': 'Anh Phong giải thích: đầu tháng mười, lợi suất trái phiếu chính phủ Mỹ kỳ hạn mười năm từng lên năm phẩy ba phần trăm, quỹ nào cũng phải so Việt Nam với con số đó. Một lý do lớn khác là giới đầu tư lo ngại hiệu quả của làn sóng chi tiêu cho trí tuệ nhân tạo, nên cổ phiếu công nghệ ở Đài Loan, Hàn Quốc bị bán mạnh. Nhưng tiền không bỏ châu Á mãi. Ấn Độ, sau hai tháng bị bán, tính đến khoảng ngày mười tháng mười một đã được mua ròng trở lại hơn năm tỷ rưỡi đô la.'}, {'k': 'cards', 'ch': 'Chương 5 – Tiền nâng hạng đi theo lịch', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('TIỀN QUỸ CHỈ SỐ', 'ĐI THEO LỊCH, KHÔNG THEO TIN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('1/12/2026', 'MSCI đổi rổ cận biên', 'Hiệu lực'), ('31,25%', 'Tỷ trọng Việt Nam trong rổ', 'Cao nhất rổ'), ('Tháng 2/2027', 'Kỳ rà soát MSCI tiếp theo', 'Công bố')], 'say': 'Còn chuyện nâng hạng thì sao? Ngày mười hai tháng mười một, MSCI công bố thay đổi rổ chỉ số thị trường cận biên: thêm hai cổ phiếu Việt Nam, loại ba mã, hiệu lực từ ngày một tháng mười hai. Đây chưa phải nâng hạng, mà là kỳ rà soát định kỳ của MSCI. Việt Nam chiếm hơn ba mươi mốt phần trăm rổ này. Với FTSE, Việt Nam đã được nâng hạng từ hai mươi mốt tháng chín. Theo ước tính của một chuyên gia Chứng khoán Kirin, từ đó tới nay quỹ thụ động mới vào khoảng hai trăm đến ba trăm triệu đô la. Tổng số dự kiến là hai phẩy hai đến hai phẩy bốn tỷ đô la, phần lớn sang năm sau.'}, {'k': 'chat', 'ch': 'Chương 6 – Chị Hạnh có đang cầm túi?', 'cap': ('"MẸ ĐANG LỖ BAO NHIÊU', 'MẸ TÍNH CHƯA?"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Vy', 'tv': 'Đang hoạt động', 'gio': '22:00', 'mau': (56, 189, 248), 'msgs': [('Vy', 'Mẹ ơi, nhóm chợ hoảng quá, mẹ đang lỗ bao nhiêu rồi?'), ('me', 'Mẹ chưa tính, chỉ thấy đỏ hết'), ('Vy', 'Mẹ tính ra số đi, rồi mới quyết')]}, 'say': 'Vy, con gái chị học năm ba ngành tài chính, nhắn về: mẹ ơi, nhóm chợ hoảng quá, mẹ đang lỗ bao nhiêu rồi? Chị Hạnh thú thật: mẹ chưa tính, chỉ thấy bảng giá đỏ hết. Vy trả lời: mẹ tính ra con số rồi hãy quyết. Chị lấy cuốn sổ tiền hàng ra, lật sang trang trắng.'}, {'k': 'giay', 'anh': 'Tan Dinh Market||Ben Thanh Market', 'cap': ('TẠM LỖ 18 TRIỆU', 'TÍNH TỪ CUỐI THÁNG 10'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'TRANG SỔ CỦA CHỊ HẠNH', 'so': 'Vốn tự có 600 triệu, không vay', 'dau': 'ĐÃ TÍNH', 'dieu': [('VN-Index cuối tháng 10: 1.741,62 điểm.', 'MỐC'), ('Phiên 19/11: 1.689,62 điểm, giảm khoảng 3%.', 'GIẢM 3%'), ('Nếu danh mục đi cùng chỉ số: tạm lỗ khoảng 18 triệu.', 'TẠM LỖ'), ('Không vay: không bị gọi thêm tiền, không bị bán giải chấp.', 'KHÔNG ÁP LỰC')]}, 'say': 'Em giả định danh mục của chị Hạnh đi đúng bằng chỉ số. Từ cuối tháng mười đến phiên mười chín tháng mười một, VN Index giảm khoảng ba phần trăm. Với sáu trăm triệu, chị đang tạm lỗ khoảng mười tám triệu đồng. Nhưng chị không vay, nên không ai gọi chị nộp thêm tiền, cũng không ai bán giải chấp thay chị.'}, {'k': 'checklist', 'anh': 'Tan Dinh Market||Ben Thanh Market', 'cap': ('NGƯỜI CẦM TÚI THẬT', 'THƯỜNG CÓ 4 DẤU HIỆU'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'items': [('Mua bằng tiền vay', (239, 68, 68)), ('Mua vì nghe tin, không hiểu doanh nghiệp', (239, 68, 68)), ('Cần dùng tiền đó trong vài tháng', (239, 68, 68)), ('Dồn hết một lần ở một mức giá', (255, 196, 0))], 'say': 'Cú lật thứ ba: người cầm túi không do ai bán cho mình quyết định, mà do cách mình mua. Một là mua bằng tiền vay, hai là mua vì nghe tin mà không biết doanh nghiệp làm ăn ra sao. Ba là cần dùng tiền đó trong vài tháng tới, bốn là dồn hết một lần ở một mức giá. Có từ hai dấu hiệu trở lên thì khối ngoại bán hay mua, rủi ro vẫn nằm ở phía mình.'}, {'k': 'chat', 'cap': ('"MẸ DÍNH MẤY DẤU HIỆU?"', '"MỘT THÔI: NGHE NHÓM CHỢ"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'chat': {'ten': 'Vy', 'tv': 'Đang hoạt động', 'gio': '22:15', 'mau': (56, 189, 248), 'msgs': [('Vy', 'Mẹ dính mấy dấu hiệu?'), ('me', 'Một thôi: mẹ hay mua theo nhóm chợ'), ('Vy', 'Vậy mẹ tắt bớt thông báo nhóm đi')]}, 'say': 'Chị Hạnh chụp trang sổ gửi cho Vy. Vy hỏi: mẹ dính mấy dấu hiệu? Chị đếm lại và trả lời thật: một thôi, mẹ hay mua theo nhóm chợ. Vy nhắn: vậy mẹ tắt bớt thông báo nhóm đi.'}, {'k': 'checklist', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('4 VIỆC NÊN LÀM', 'KHI ĐỌC TIN KHỐI NGOẠI BÁN'), 'cols': ((255, 255, 255), (34, 197, 94)), 'moc': True, 'items': [('Tách khớp lệnh và thỏa thuận', (34, 197, 94)), ('Nhìn cả khu vực trước khi hoảng', (34, 197, 94)), ('Tiền nâng hạng đi theo lịch', (34, 197, 94)), ('Không vay để bắt đáy', (255, 196, 0))], 'say': 'Với anh chị, em gợi ý bốn việc khi đọc tin khối ngoại bán ròng. Thứ nhất, tìm xem bao nhiêu là khớp lệnh, bao nhiêu là thỏa thuận. Thứ hai, nhìn sang Đài Loan, Hàn Quốc xem đó là chuyện riêng Việt Nam hay cả khu vực. Thứ ba, nhớ rằng tiền nâng hạng đi theo lịch của các quỹ chỉ số, không theo tin đồn. Thứ tư, khi tiền ngoại còn đang rút, đừng dùng tiền vay để bắt đáy.'}, {'k': 'chat', 'ch': 'Kết – Trang sổ cuối ngày', 'cap': ('"EM KHÔNG BÁN', 'CŨNG KHÔNG VAY ĐỂ MUA"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Anh Sơn', 'tv': 'Đang hoạt động', 'gio': '22:30', 'mau': (34, 197, 94), 'msgs': [('me', 'Em không bán, cũng không vay để mua thêm'), ('Anh Sơn', 'Ừ, miễn đừng vay là anh yên tâm')]}, 'say': 'Mười giờ rưỡi tối thứ Năm, chị Hạnh nhắn cho chồng: em không bán, cũng không vay để mua thêm. Rồi chị tắt thông báo nhóm Zalo của chợ.'}, {'k': 'end', 'anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'cap': ('ANH CHỊ DÍNH MẤY DẤU HIỆU?', 'GÕ SỐ 0 ĐẾN 4'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Số liệu lợi nhuận doanh nghiệp từng quý, anh chị có thể tra miễn phí trên chứng khoán Huy Nguyễn chấm com. Còn bây giờ, gõ một con số từ không đến bốn: trong bốn dấu hiệu cầm túi vừa rồi, anh chị đang dính mấy cái?'}]
META = {'NONG2111A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Tin nóng trong ngày', 'ngay': '2026-11-20', 'gio_goi_y': '20:00', 'gio': '20:00', 'nhac': 'lofi', 'tieu_de': 'Khối Ngoại Xả 122.000 Tỷ – Nhà Đầu Tư Cá Nhân Có Cầm Túi?', 'title': 'Khối Ngoại Xả 122.000 Tỷ – Nhà Đầu Tư Cá Nhân Có Cầm Túi?', 'mo_ta': 'NÓNG 18–19/11/2026: VN-Index mất 37 điểm trong hai phiên, thủng mốc 1.700, khối ngoại bán ròng khoảng 2.100 tỷ đồng (gộp hai phiên). Từ đầu năm, khối ngoại đã bán ròng gần 122.000 tỷ trên HOSE, gần bằng cả năm 2025, năm bán ròng kỷ lục. Người nước ngoài bán thì ai đang mua? Nhà đầu tư cá nhân có đang "cầm túi"? Video bóc từng lớp: khớp lệnh và thỏa thuận, làn sóng rút vốn khỏi 7 thị trường châu Á, tiền đổ vào Mỹ, kỳ rà soát MSCI 1/12 và lịch tiền FTSE, cùng 4 dấu hiệu của người cầm túi thật.\n\nNguồn số liệu:\n• Phiên 18/11/2026: VN-Index 1.703,01 điểm (-23,71 điểm); 539 mã giảm; khối ngoại bán ròng 1.113,55 tỷ trên HOSE (Vietstock, VietnamPlus 18/11/2026)\n• Phiên 19/11/2026: VN-Index 1.689,62 điểm (-13,39 điểm), thấp nhất một tháng; khối ngoại bán ròng khoảng 995 tỷ (VietnamPlus, VnExpress 19/11/2026)\n• 10 tháng 2026: khối ngoại bán ròng gần 122.000 tỷ trên HOSE, chưa tháng nào mua ròng (Vietstock 11/2026); cả năm 2025 bán ròng kỷ lục 135.329 tỷ, khoảng 5,2 tỷ USD (VnEconomy); tháng 10/2026 bán ròng 23.705 tỷ, 20/22 phiên (Báo Đấu thầu 05/11/2026; Vietstock)\n• Nhà đầu tư trong nước mua ròng hơn 123.000 tỷ trên HOSE từ đầu năm đến 4/11/2026 (Tạp chí Sở hữu trí tuệ qua MoneyF 05/11/2026)\n• Tuần 5–9/10/2026: khối ngoại bán ròng 13.921 tỷ, riêng khớp lệnh 1.269,4 tỷ; một lô thỏa thuận khoảng 9.600 tỷ bán cho nhà đầu tư trong nước (VnEconomy 11/10/2026)\n• Tháng 10/2026: khối ngoại bán ròng 49,77 tỷ USD ở 7 thị trường châu Á mới nổi (gồm Việt Nam); Đài Loan 30,68 tỷ USD (cao nhất ít nhất từ 1/2008); Hàn Quốc 14,59 tỷ USD; Ấn Độ mua ròng 5,68 tỷ USD từ đầu tháng 11 đến khoảng 10/11; lợi suất trái phiếu Mỹ 10 năm 5,3% đầu tháng 10 (LSEG, qua VietnamPlus/Vietstock 12/11/2026)\n• Tuần 9–13/11/2026: ETF cổ phiếu Mỹ hút ròng 55,44 tỷ USD (VnEconomy 17/11/2026)\n• MSCI rà soát định kỳ tháng 11/2026: rổ Frontier thêm 2 mã, loại 3 mã Việt Nam, hiệu lực 1/12/2026; Việt Nam chiếm 31,25% rổ; kỳ sau công bố tháng 2/2027 (MSCI 11/11/2026 giờ Mỹ; Người Quan Sát 12/11/2026)\n• FTSE nâng hạng hiệu lực 21/9/2026; quỹ thụ động có thể giải ngân 2,2–2,4 tỷ USD trong một năm, mới khoảng 200–300 triệu USD từ 21/9, phần lớn vào 2027 – ước tính chuyên gia Chứng khoán Kirin (Vietstock 11/2026)\n• Tự tính: 23,71 + 13,39 ≈ 37 điểm; 1.113,55 + 995 ≈ 2.109 tỷ (gộp số HOSE phiên 18/11 và số chung phiên 19/11); (13.921 − 1.269,4) / 13.921 ≈ 91% thỏa thuận; VN-Index 1.741,62 → 1.689,62 ≈ −3%; 600 triệu × 3% ≈ 18 triệu (giả định danh mục đi cùng chỉ số)\n\nTra lợi nhuận doanh nghiệp từng quý: https://chungkhoanhuynguyen.com\nCần trao đổi riêng về danh mục: Zalo 0365.188.286\n\nNhân vật chị Hạnh, anh Sơn, anh Phong, Vy là hư cấu; số liệu là thật theo nguồn trên.\nChia sẻ góc nhìn, không phải khuyến nghị mua bán.\n\nTừ khoá: khối ngoại bán ròng, khối ngoại bán ròng hôm nay, VN-Index thủng 1700, MSCI tháng 11/2026, FTSE nâng hạng, dòng tiền ngoại, chứng khoán hôm nay, nhà đầu tư cá nhân', 'tags': ['khối ngoại bán ròng', 'khối ngoại bán ròng hôm nay', 'VN-Index thủng 1700', 'dòng tiền khối ngoại', 'MSCI tháng 11 2026', 'FTSE nâng hạng', 'MSCI rà soát', 'chứng khoán hôm nay', 'tin nóng chứng khoán', 'nhà đầu tư cá nhân'], 'bia_hook': ['TÂY XẢ 122.000 TỶ', 'ANH CHỊ ĐANG CẦM TÚI?'], 'badge': 'NÓNG: VN-INDEX THỦNG 1.700', 'bia_anh': 'Ho Chi Minh City Stock Exchange||Bitexco Financial Tower', 'bia_hook_b': ['TÂY BÁN, TA MUA', 'AI CẦM TÚI?'], 'badge_b': 'TIỀN NGOẠI ĐI ĐÂU', 'bia_hook_c': ['13.921 TỶ BÁN RÒNG', 'CHỈ 1.269 TỶ KHỚP LỆNH'], 'badge_c': 'PHẦN LỚN LÀ THỎA THUẬN', 'reel_hook': 'TÂY XẢ 122.000 TỶ|ANH CHỊ ĐANG CẦM TÚI?', 'fb_post': 'Khối ngoại bán ròng gần 122.000 tỷ từ đầu năm, hai phiên 18–19/11 thêm khoảng 2.100 tỷ, VN-Index thủng 1.700.\n\nNgười nước ngoài bán thì ai đang mua? Nhà đầu tư cá nhân có đang cầm túi?\n\n- Có tuần bán ròng 13.921 tỷ nhưng chỉ 1.269 tỷ là khớp lệnh\n- 7 thị trường châu Á bị rút gần 50 tỷ USD trong tháng 10, Đài Loan cao nhất từ 2008\n- Cùng lúc, ETF cổ phiếu Mỹ hút hơn 55 tỷ USD trong một tuần\n\nVà 4 dấu hiệu của người cầm túi thật – anh chị dính mấy cái? Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Hai phiên mất 37 điểm', 'Chương 2 – Ai đang mua đối ứng?', 'Chương 3 – Tuần bán mạnh nhất: phần lớn là thỏa thuận', 'Chương 4 – Tiền ngoại rút đi đâu?', 'Chương 5 – Tiền nâng hạng đi theo lịch', 'Chương 6 – Chị Hạnh có đang cầm túi?', 'Kết – Trang sổ cuối ngày'], 'seri_web': 'Tin nóng trong ngày'}}
